using Nakama.Api.BuildingBlocks.Time; using Nakama.Api.Modules.Tasks.Domain; using Xunit;
namespace Nakama.Api.Tests.Tasks;
public sealed class SubtaskTests{static readonly Guid Id=Guid.NewGuid();static readonly DateTimeOffset Now=new(2026,1,1,0,0,0,TimeSpan.Zero);[Fact]public void Create_normalizes_and_starts_open(){var s=Subtask.Create(Id,"  Check  ",1,Id,new C(Now));Assert.Equal("Check",s.Title);Assert.False(s.IsCompleted);Assert.Null(s.CompletedAt);Assert.Null(s.CompletedByUserId);}[Fact]public void Completion_can_be_reopened(){var s=Subtask.Create(Id,"X",1,Id,new C(Now));s.Complete(Id,new C(Now));Assert.Throws<InvalidOperationException>(()=>s.Complete(Id,new C(Now)));s.Reopen(new C(Now));Assert.False(s.IsCompleted);Assert.Null(s.CompletedAt);Assert.Throws<InvalidOperationException>(()=>s.Reopen(new C(Now)));}[Fact]public void Empty_title_is_invalid()=>Assert.Throws<ArgumentException>(()=>Subtask.Create(Id," ",1,Id,new C(Now)));sealed class C(DateTimeOffset n):IClock{public DateTimeOffset UtcNow=>n;}}
